  "#!/bin/sh # awg-panel: после перевыпуска сертификата XRay должен перечитать его с диска. # Инбаунд Hysteria терминирует QUIC этим же сертификатом, а файлы читаются при # старте процесса — без перезапуска клиенты упрутся в просроченный сертификат. systemctl is-active --quiet xray && systemctl restart xray exit 0": "#!/bin/sh # awg-panel: after the certificate is reissued, XRay must re-read it from disk. # The Hysteria inbound terminates QUIC with this same certificate, and the files are read at # process start — without a restart clients will hit an expired certificate. systemctl is-active --quiet xray && systemctl restart xray exit 0",
