  "#!/bin/sh # Создано панелью awg-panel: сертификат перечитывается только при старте, # поэтому после перевыпуска надо поднять всех его потребителей. systemctl try-restart": "#!/bin/sh # Created by the awg-panel panel: the certificate is re-read only at start, # so after reissuing, all its consumers must be restarted. systemctl try-restart",
  ".service systemctl reload nginx 2>/dev/null || true # XRay держит сертификат только в режиме TLS; при Reality файла в конфиге # нет и перезапуск не нужен — лишний разрыв сессий ни к чему. if grep -q certificateFile /usr/local/etc/xray/config.json 2>/dev/null; then systemctl try-restart xray.service fi": ".service systemctl reload nginx 2>/dev/null || true # XRay holds the certificate only in TLS mode; with Reality there is no file in the config # and no restart is needed — an extra session drop is pointless. if grep -q certificateFile /usr/local/etc/xray/config.json 2>/dev/null; then systemctl try-restart xray.service fi",
