  "# awg-panel: Telegram WEB-прокси": "# awg-panel: Telegram WEB proxy",
  ". Файл генерирует панель — ручные правки перезапишутся. map $http_upgrade $awg_tgweb_upgrade { default upgrade; '' ''; } server { listen 127.0.0.1:": ". The file is generated by the panel — manual edits will be overwritten. map $http_upgrade $awg_tgweb_upgrade { default upgrade; '' ''; } server { listen 127.0.0.1:",
  "nginx не установлен": "nginx is not installed",
  "nginx установлен, но не запустился": "nginx is installed but failed to start",
  "proxy_protocol; server_name _; # Журнала нет на всём блоке: в строках запросов лежат ключи моста # (?bridge=) и секретный адрес входа в панель. До WEB-прокси эти # запросы шли из XRay прямо во Flask и в журналы nginx не попадали. access_log off; # WEB-прокси Telegram. Префикс без ручных правок не менять: он зашит # в каждую выданную ссылку. location ^~ /": "proxy_protocol; server_name _; # No log on the whole block: request lines contain bridge keys # (?bridge=) and the secret panel entry address. Before the WEB proxy, these # requests went from XRay straight to Flask and did not end up in nginx logs. access_log off; # Telegram WEB proxy. Do not change the prefix without manual edits: it is baked # into every issued link. location ^~ /",
  "# (ему нужен публичный адрес в ответе socks), а рекламный тег WEB не нужен.": "# (it needs a public address in the socks reply), and the WEB ad tag is not needed.",
  "# https-lanes нужен HTTP/2, которого XRay с ALPN http/1.1 не даёт.": "# https-lanes needs HTTP/2, which XRay with ALPN http/1.1 does not provide.",
  "# iOS понимает только https; WebSocket в РФ режут после ~2 МиБ, а": "# iOS only understands https; WebSocket in Russia is cut after ~2 MiB, and",
  "# Генерирует awg-panel (Telegram WEB-прокси). Ручные правки перезапишутся:": "# Generated by awg-panel (Telegram WEB proxy). Manual edits will be overwritten:",
  "# Напрямую к DC Telegram: middle-proxy через socks каскада не работает": "# Directly to the Telegram DC: middle-proxy does not work through the cascade socks",
  "# Не трогать netfilter сервера: фаерволом и conntrack управляет панель.": "# Do not touch the server's netfilter: the firewall and conntrack are managed by the panel.",
  "# Профиль TLS чужого сайта нужен только классическому FakeTLS — не WEB.": "# The TLS profile of a third-party site is only needed for classic FakeTLS, not WEB.",
  "# источник — data/tgweb/settings.json и clients.json.": "# source: data/tgweb/settings.json and clients.json.",
  ". WEB-прокси нужен настоящий сертификат нашего домена — переключите XRay в режим TLS (⚙ XRay → «Режим на 443»).": ". The WEB proxy needs a real certificate for our domain; switch XRay to TLS mode (⚙ XRay → «Mode on 443»).",
